}

// per-mechanism DSL so students can write a test without writing a Command
SelfTest.register("Arm", () -> MechanismTest.of(arm)
    .step("extend",  arm.toAngle(Degrees.of(90)))
        .expect(arm::angle, Degrees.of(90), Degrees.of(2))
        .withTimeout(Seconds.of(2))
    .step("retract", arm.toAngle(Degrees.of(0)))
        .expect(arm::angle, Degrees.of(0),  Degrees.of(2))
    .expectCurrentBetween(Amps.of(2), Amps.of(35))
    .expectNoNewFaults()
    .build());

